def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        rows = {}
        for name in names:
            rows[name] = {r["version"]: r for r in packages[name]}
        # Enumerate vectors in required lexicographically descending order.
        choices = []
        for name in names:
            versions = sorted(rows[name], reverse=True)
            choices.append(versions + [-1])

        for vector in product(*choices):
            assigned = dict(zip(names, vector))
            edges = {}
            valid = True
            for name, bounds in roots.items():
                v = assigned[name]
                if v < bounds[0] or v > bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, version in assigned.items():
                if version == -1:
                    continue
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    valid = False
                    break
                deps = []
                for dep in rows[name][version].get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    target_version = assigned[target]
                    if not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    deps.append(target)
                edges[name] = deps
                if not valid:
                    break
            if not valid:
                continue
            # Installed packages must be exactly the closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                if assigned[name] == -1:
                    valid = False
                    break
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if not valid or any((v != -1) != (name in reachable)
                                for name, v in assigned.items()):
                continue
            active, done = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                done.add(name)
                return True

            if not all(visit(name) for name in reachable):
                continue
            return {"versions": {name: assigned[name] for name in names
                                 if assigned[name] != -1}}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    from itertools import combinations
    import heapq

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_ids = None
        options = [j for j in jobs if j["id"] not in blocked]
        for subset in combinations(options, k):
            ids = tuple(sorted(j["id"] for j in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            if any(counts.get(group, 0) > high
                   for group, (low, high) in quotas.items()):
                continue
            ends = []
            overlap_ok = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
                while ends and ends[0] <= job["start"]:
                    heapq.heappop(ends)
                heapq.heappush(ends, job["end"])
                if len(ends) > 2:
                    overlap_ok = False
                    break
            if not overlap_ok:
                continue
            value = sum(j["value"] for j in subset)
            if best is None or value > best or (value == best and ids < best_ids):
                best, best_ids = value, ids
        if best is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best}
    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        dist = {start_state: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        while queue:
            time, node, mask, left = heapq.heappop(queue)
            state = (node, mask, left)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                durations = [(edge["duration"], left)]
                if left:
                    durations.append((max(2, edge["duration"] - edge.get("discount", 0)), left - 1))
                for duration, remaining in durations:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    next_mask = mask | bit.get(dest, 0)
                    next_state = (dest, next_mask, remaining)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, dest, next_mask, remaining))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
